  const preferredPrivacy=personId?(await database().prepare("SELECT default_privacy FROM person_financial_preferences WHERE tenant_id=? AND person_id=?").bind(ctx.session.user.tenantId,personId).first<{default_privacy:FinancePrivacy}>())?.default_privacy:null;
