  if(type==="CONTRIBUTION") { try { contributionIdentity(privacy,personId); } catch { throw new ApiError(400,"CONTRIBUINTE_OBRIGATORIO","Selecione uma Pessoa ou marque a contribuição como anônima."); } }
  const description=clean(input.description,300)|| (type==="CONTRIBUTION"?"Contribuição":"Lançamento manual"),movementCompetency=competency(input.competency),period=await assertOpenFinancePeriodById(ctx.session,account.unit_id,input.periodId?positiveId(input.periodId):0),createdDuringReopening=period.closure_version>0?1:0;
  const movement=database().prepare("INSERT INTO finance_movements(id,tenant_id,unit_id,account_id,direction,amount_cents,occurred_on,competency,description,category_id,payment_method_id,person_id,cost_center_id,department_id,campaign_id,fund_id,source,source_entity,source_entity_id,privacy,idempotency_key,created_by_user_id,created_at,updated_at,period_id,created_during_reopening) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(movementId,tenant,account.unit_id,account.id,direction,amount,isoDate(input.occurredOn),movementCompetency,description,categoryId,paymentMethodId,privacy==="ANONIMA"?null:personId,costCenterId,positiveId(input.departmentId,false),campaignIdInput,fundId,["MANUAL","EBD","CAMPANHA","CONTA_RECEBER","OUTRO"].includes(clean(input.source,30))?clean(input.source,30):"MANUAL",clean(input.sourceEntity,60)||null,positiveId(input.sourceEntityId,false),privacy,clean(input.idempotencyKey,100)||null,ctx.session.user.id,stamp,stamp,period.id,createdDuringReopening);
  const statements=[movement];
  if(type==="CONTRIBUTION") { const contributionType=clean(input.contributionType,30); if(!["DIZIMO","OFERTA","VOTO","DOACAO","MISSOES","CAMPANHA","OFERTA_VOLUNTARIA","OUTRA"].includes(contributionType)) throw new ApiError(400,"DADOS_INVALIDOS","Tipo de contribuição inválido."); statements.push(database().prepare("INSERT INTO finance_contributions(id,tenant_id,movement_id,contribution_type,person_id,privacy,created_at) VALUES(?,?,?,?,?,?,?)").bind(generatedId(),tenant,movementId,contributionType,privacy==="ANONIMA"?null:personId,privacy,stamp)); }
