  if(costCenterId){const row=await owned<{unit_id:number;status:string}>("finance_cost_centers",ctx,costCenterId);if(row.unit_id!==unitId||row.status!=="ATIVO")throw new ApiError(403,"FORA_DO_ESCOPO","Centro de custo inválido para a unidade.");}
  if(campaignId){const row=await owned<{unit_id:number;status:string}>("finance_campaigns",ctx,campaignId);if(row.unit_id!==unitId||row.status!=="ATIVA")throw new ApiError(403,"FORA_DO_ESCOPO","Campanha inválida para a unidade.");}
  if(fundId){const row=await owned<{unit_id:number;status:string}>("finance_funds",ctx,fundId);if(row.unit_id!==unitId||row.status!=="ATIVO")throw new ApiError(403,"FORA_DO_ESCOPO","Fundo inválido para a unidade.");}
